def _binary_formula_for(element, oxi_state):
    """
    Return the expected binary oxide formula for a cation at a
    given oxidation state, plus the cation and oxygen counts
    per formula unit of that binary.

    Returns (formula_str, n_cations, n_oxygens) or (None, None, None).
    """
    oxi = round(abs(oxi_state))

    # ── Special cases ─────────────────────────────────────────────
    # Co3O4 spinel: Co2+[Co3+]2O4. Use as the Co3+ reference.
    # Decomposition: 1 Co3+ requires 1/3 Co3O4 (3 Co per fu),
    # contributing 4/3 O per Co3+.
    if element == "Co" and oxi == 3:
        return ("Co3O4", 3, 4)

    patterns = {
        1: (f"{element}2O",  2, 1),
        2: (f"{element}O",   1, 1),
        3: (f"{element}2O3", 2, 3),
        4: (f"{element}O2",  1, 2),
        5: (f"{element}2O5", 2, 5),
        6: (f"{element}O3",  1, 3),
        7: (f"{element}2O7", 2, 7),
    }
    return patterns.get(oxi, (None, None, None))


def decompose_ternary(source_cif, df_results, binary_lookup, verbose=True,
                      results_index=None):
    """
    Decompose a ternary oxide into binary components using the
    per-site oxidation states from MaplePy output.

    Parameters
    ----------
    source_cif     : str   filename from maple_summary/results
    df_results     : DataFrame  site-level MaplePy output
    binary_lookup  : dict  {formula: maple_kcal_mol}
    verbose        : bool

    Returns
    -------
    dict with keys:
        source_cif, compound, maple_ternary,
        decomposition (list of dicts per cation element),
        maple_binary_sum, delta_abs, delta_pct,
        oxygen_balanced, missing_binaries, success
    """
    # v1.2.4: from the index where the caller built one; the scan it
    # replaces cost 2.4 ms of the 5.4 ms this function took per structure.
    sites = rows_for(source_cif, df_results, results_index).copy()

    if sites.empty:
        return {"source_cif": source_cif, "success": False,
                "error": "No site data found"}

    compound     = sites['compound'].iloc[0]
    maple_tern   = sites['total_maple'].iloc[0]
    Z            = sites['Z'].iloc[0]

    # ── Identify cations and their mean oxidation states ──────────────
    cation_sites = sites[sites['oxidation_state'] > 0]
    anion_sites  = sites[sites['oxidation_state'] < 0]

    if cation_sites.empty:
        return {"source_cif": source_cif, "compound": compound,
                "success": False, "error": "No cation sites identified"}

    cation_info = {}
    for el in cation_sites['element'].unique():
        el_sites = cation_sites[cation_sites['element'] == el]
        cation_info[el] = {
            'count_per_fu': len(el_sites) / Z,
            'mean_oxi': el_sites['oxidation_state'].mean(),
            'sites_in_cell': len(el_sites),
        }

    o_per_fu = len(anion_sites) / Z

    # ── Decompose each cation into its binary ─────────────────────────
    decomposition = []
    maple_sum     = 0.0
    o_from_binary = 0.0
    missing       = []
    # v1.2.3: what was asked for and why it was not there, one entry per
    # missing binary. `missing_binaries` stays as it was, for the report and
    # for every CSV already written.
    missing_detail = []
    estimated_used = []     # v1.2.9: binaries whose value is an estimate

    for el, info in cation_info.items():
        binary_formula, n_cat, n_oxy = _binary_formula_for(
            el, info['mean_oxi']
        )

        # v1.2.3: did the pattern lookup have to round? A mean over a
        # shared site is not an oxidation state, and the rounding was silent.
        _mean = abs(info['mean_oxi'])
        _rounded = abs(_mean - round(_mean)) > OXI_ROUNDING_TOL

        if binary_formula is None:
            missing.append(f"{el}{info['mean_oxi']:+.1f} (no pattern)")
            missing_detail.append({
                'binary': None, 'element': el,
                'mean_oxi': round(info['mean_oxi'], 3),
                'rounded_from_non_integer': _rounded,
                'reason': 'no binary pattern for this oxidation state'})
            continue

        maple_binary = binary_lookup.get(binary_formula)
        if maple_binary is None:
            # v1.2.5: the rounding fact goes IN the string. It used to live in
            # missing_detail, a parallel list that batch_additivity never put
            # into its frame, so the classifier's best evidence never reached
            # it. One carrier, and it is the one that survives to the CSV.
            missing.append(
                f"{binary_formula} (not in table"
                + (f", mean {info['mean_oxi']:+.2f} rounded)" if _rounded
                   else ")"))
            missing_detail.append({
                'binary': binary_formula, 'element': el,
                'mean_oxi': round(info['mean_oxi'], 3),
                'rounded_from_non_integer': _rounded,
                'reason': 'not in the reference table'})
            continue

        # v1.2.9: an estimate is used, and said to be used
        if binary_formula in ESTIMATED_BINARIES:
            estimated_used.append(binary_formula)

        coeff = info['count_per_fu'] / n_cat
        contribution = coeff * maple_binary
        o_contrib    = coeff * n_oxy

        decomposition.append({
            'element'      : el,
            'oxi_state'    : round(info['mean_oxi'], 2),
            'binary'       : binary_formula,
            'n_cat_binary' : n_cat,
            'n_oxy_binary' : n_oxy,
            'coeff'        : round(coeff, 4),
            'maple_binary' : round(maple_binary, 2),
            'contribution' : round(contribution, 2),
            'o_from_binary': round(o_contrib, 4),
        })

        maple_sum     += contribution
        o_from_binary += o_contrib

    # ── Oxygen balance check ──────────────────────────────────────────
    #
    # v1.1: MEASURED, AND LEFT ALONE. This is an absolute tolerance on a
    # quantity that scales as 1/Z, which is the shape of a fault. Over 101
    # decompositions of real ICSD structures the imbalance is:
    #
    #        0 to 1e-6      97 structures      exact, to floating point
    #     1e-6 to 0.1        0
    #      0.1 to 0.2        3                 Co3O4 standing in for Co2O3
    #      0.2 and above     1                 Ca4Mn4O10.6
    #
    # Nothing lies inside the gap, so every value between about 1e-6 and 0.16
    # classifies identically and the number is not doing the work. What DID
    # matter was the Z error upstream: at Z = 1 the same physical imbalance
    # was multiplied by the true Z, close enough to the gap to cross it.
    # MaplePy v1.1 derives Z crystallographically and removes that.
    #
    # Note also that o_per_fu counts anion SITES, not occupancies, so an
    # oxygen-deficient refinement is balanced here and non-stoichiometric in
    # its composition. That is consistent with the mean-field treatment
    # elsewhere and is worth stating rather than discovering.
    O_BALANCE_TOL = 0.05          # O per formula unit; see the measurement above
    o_residual = abs(o_from_binary - o_per_fu)
    o_balanced = o_residual < O_BALANCE_TOL

    # ── Additivity residual ───────────────────────────────────────────
    #
    # v1.2.1: `if decomposition` asks whether ANY cation was decomposed, not
    # whether ALL were. 30 structures across the two families are missing a
    # binary reference, so their sum omitted a whole component and the
    # residual against it was up to 93% (NaOsO3: ternary 5022.2 against Na2O
    # alone at 347.2). success=False kept those out of the statistics, but the
    # number was still written to the CSV and Figure 1 selected on
    # delta.notna(), so all 30 sat in the histogram tail looking like
    # measured failures.
    #
    # Same rule as the falsy-zero fix above: do not write a number that has no
    # meaning. missing_binaries still says what was absent.
    complete = bool(decomposition) and not missing
    delta_abs = abs(maple_tern - maple_sum) if complete else None
    delta_pct = (100 * delta_abs / maple_tern
                 if delta_abs is not None and maple_tern > 0
                 else None)

    result = {
        'source_cif'       : source_cif,
        'compound'         : compound,
        'maple_ternary'    : round(maple_tern, 2),
        'Z'                : Z,
        'n_cation_elements': len(cation_info),
        'decomposition'    : decomposition,
        'maple_binary_sum' : round(maple_sum, 2),
        # v1.1: `if delta_abs` is FALSE for 0.0, so a structure whose
        # ternary MAPLE exactly equalled its binary sum - the perfect result
        # the theorem predicts - was written out as None and then read
        # downstream as a missing value. The guard in the classifier
        # attributed it to "a rounding or serialisation artefact"; it was
        # this line.
        'delta_abs'        : (round(delta_abs, 2)
                              if delta_abs is not None else None),
        'delta_pct'        : (round(delta_pct, 3)
                              if delta_pct is not None else None),
        'oxygen_per_fu'    : round(o_per_fu, 4),
        'oxygen_from_bins' : round(o_from_binary, 4),
        'oxygen_balanced'  : o_balanced,
        'missing_binaries' : missing,
        'missing_detail'   : missing_detail,
        'estimated_binaries': estimated_used,
        'success'          : len(decomposition) > 0 and len(missing) == 0,
    }

    if verbose and result['success']:
        status = (f"GOOD (<{ADDITIVE_THRESHOLD_PCT:g}%)"
                  if delta_pct < ADDITIVE_THRESHOLD_PCT else
                  "MARGINAL (1-2%)" if delta_pct < 2.0 else
                  "POOR (>2%)")
        print(f"  {compound:20s}  "
              f"MAPLE={maple_tern:8.1f}  "
              f"sum={maple_sum:8.1f}  "
              f"delta={delta_pct:.2f}%  {status}"
              f"{'  [O imbalanced]' if not o_balanced else ''}")
    elif verbose and not result['success']:
        print(f"  {compound:20s}  INCOMPLETE: missing {missing}")

    return result


print("Decomposition function defined.")